  return {
    packet: context.packetDir,
    packetLabel: context.packetLabel,
    phaseChildCount: context.phaseChildren.length,
    isPhaseChild: context.isPhaseChild,
    checks,
    errors,
    contextError: false,
    passed: errors.length === 0 && checks.every((check) => check.findings.length === 0)
  };
}

